const key=s=>String(s||'').normalize('NFD').replace(/[̀-ͯ]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const aliases={piyomon:'biyomon',vmon:'veemon',shakomon:'syakomon',plotmon:'salamon',dracumon:'dracmon',flamon:'flamemon',gabumonblack:'blackgabumon'};
export function findSheetArt(name,stage=''){const n=key(name),canonical=aliases[n]||n;return sheetArt.find(a=>(!stage||a.stage===stage)&&(key(a.name)===canonical||key(a.id)===canonical));}
export function sheetSprite(name,fallback='',stage=''){return findSheetArt(name,stage)?.image||fallback;}
export function sceneSprite(form){
 const art=findSheetArt(form.name,form.stage);
 return art&&(!form.image||form.image===art.sourceImage||form.image===art.source)?art.image:form.image;
}
